class Solution:

	def is1winner(self, N, arr):
		dp = [[-1 for i in range(len(arr))] for j in range(len(arr))]

		def playGame(l, r):
			if l > r:
				return 0
			if l == r:
				return arr[r]
			if dp[l][r] != -1:
				return dp[l][r]
			option1 = arr[l] + min(playGame(l + 2, r), playGame(l + 1, r - 1))
			option2 = arr[r] + min(playGame(l + 1, r - 1), playGame(l, r - 2))
			dp[l][r] = max(option1, option2)
			return dp[l][r]
		ans = playGame(0, len(arr) - 1)
		return int(ans > sum(arr) / 2)
